class HorizontalDividerNode extends ri {
  static getType() {
    return "horizontal_divider"
  }

  static clone(node) {
    return new HorizontalDividerNode(node.__key)
  }

  static importJSON(serializedNode) {
    return new HorizontalDividerNode()
  }

  static importDOM() {
    return {
      "hr": (hr) => {
        return {
          conversion: () => ({
            node: new HorizontalDividerNode()
          }),
          priority: 1
        }
      }
    }
  }

  constructor(key) {
    super(key);
  }

  // The hr already provides separator semantics; a figure boundary would be redundant.
  createDOM() {
    const figure = createElement("figure", { className: "horizontal-divider", role: "presentation" });
    figure.appendChild(createElement("hr"));
    figure.dataset.lexicalNodeKey = this.__key;

    return figure
  }

  updateDOM() {
    return true
  }

  getTextContent() {
    return "┄\n\n"
  }

  isInline() {
    return false
  }

  get label() {
    return "Horizontal divider"
  }

  exportDOM() {
    const hr = createElement("hr");
    return { element: hr }
  }

  exportJSON() {
    return {
      type: "horizontal_divider",
      version: 1
    }
  }

  decorate() {
    return null
  }
}

const HORIZONTAL_DIVIDER = {
  dependencies: [ HorizontalDividerNode ],
  export: (node) => {
    return node instanceof HorizontalDividerNode ? "---" : null
  },
  regExpStart: /^-{3,}\s?$/,
  replace: (parentNode, children, match, endMatch, linesInBetween, isImport) => {
    const hrNode = new HorizontalDividerNode();
    parentNode.replace(hrNode);

    if (!isImport) {
      const paragraph = os();
      hrNode.insertAfter(paragraph);
      paragraph.select();
    }
  },
  type: "multiline-element"
};

const PUNCTUATION_OR_SPACE = /[^\w]/;

